<script setup>
import { computed, onBeforeUnmount, reactive, ref, watch } from "vue";
import { onBeforeRouteLeave, useRoute, useRouter } from "vue-router";
import UniversalChildTable from "@/components/generated/UniversalChildTable.vue";
import UniversalField from "@/components/generated/UniversalField.vue";
import ErrorState from "@/components/feedback/ErrorState.vue";
import PermissionDenied from "@/components/feedback/PermissionDenied.vue";
import PageContainer from "@/components/layout/PageContainer.vue";
import { createDocument, getDocumentDetail, getMetadata, updateDocument } from "@/services/universal.js";
const route = useRoute(); const router = useRouter(); const loading = ref(true); const saving = ref(false); const error = ref(null); const metadata = ref(null); const values = reactive({}); const errors = reactive({}); const dirty = ref(false); let controller; const feature = computed(() => String(route.params.feature)); const name = computed(() => route.params.name ? String(route.params.name) : ""); const editing = computed(() => Boolean(name.value));
const visibleFields = computed(() => (metadata.value?.fields || []).filter((field) => !field.hidden && !["Section Break","Column Break","Tab Break","Table","Table MultiSelect","Button","HTML"].includes(field.fieldtype)));
const tables = computed(() => (metadata.value?.fields || []).filter((field) => !field.hidden && ["Table","Table MultiSelect"].includes(field.fieldtype)));
const sections = computed(() => {
  const result = []; let current = { key: "details", title: "Details", fields: [], tables: [] };
  const push = () => { if (current.fields.length || current.tables.length) result.push(current); };
  for (const field of metadata.value?.fields || []) {
    if (field.hidden) continue;
    if (["Section Break", "Tab Break"].includes(field.fieldtype)) { push(); current = { key: field.fieldname, title: field.label || "Details", fields: [], tables: [] }; }
    else if (["Table", "Table MultiSelect"].includes(field.fieldtype)) current.tables.push(field);
    else if (!["Column Break", "Button", "HTML"].includes(field.fieldtype)) current.fields.push(field);
  }
  push(); return result;
});
async function load() { controller?.abort(); controller = new AbortController(); loading.value = true; error.value = null; Object.keys(values).forEach((key) => delete values[key]); try { metadata.value = await getMetadata(feature.value, controller.signal); if (editing.value) { const result = await getDocumentDetail(feature.value, name.value, controller.signal); Object.assign(values, result.document); } else { Object.assign(values, metadata.value.defaults || {}); for (const field of metadata.value.fields) if (["Table","Table MultiSelect"].includes(field.fieldtype)) values[field.fieldname] = []; } dirty.value = false; } catch (caught) { if (caught.name !== "AbortError") error.value = caught; } finally { loading.value = false; } }
function change(fieldname, value) { values[fieldname] = value; delete errors[fieldname]; dirty.value = true; }
function validate() { Object.keys(errors).forEach((key) => delete errors[key]); for (const field of visibleFields.value) if (field.required && !field.read_only && (values[field.fieldname] === undefined || values[field.fieldname] === null || values[field.fieldname] === "")) errors[field.fieldname] = `${field.label} is required.`; return !Object.keys(errors).length; }
function payload() { const allowed = [...visibleFields.value, ...tables.value].filter((field) => !field.read_only).map((field) => field.fieldname); return Object.fromEntries(allowed.filter((key) => key in values).map((key) => [key, values[key]])); }
async function save(continueEditing = false) { if (saving.value || !validate()) return; saving.value = true; error.value = null; try { const result = editing.value ? await updateDocument(feature.value, name.value, payload(), values.modified) : await createDocument(feature.value, payload()); dirty.value = false; if (continueEditing) await router.replace(`/generated/${feature.value}/${encodeURIComponent(result.name)}/edit`); else await router.push(result.route); } catch (caught) { error.value = caught; } finally { saving.value = false; } }
function beforeUnload(event) { if (!dirty.value) return; event.preventDefault(); event.returnValue = ""; }
onBeforeRouteLeave(() => !dirty.value || window.confirm("Leave this page? Unsaved changes will be lost."));
watch(() => route.fullPath, load, { immediate: true }); window.addEventListener("beforeunload", beforeUnload); onBeforeUnmount(() => { controller?.abort(); window.removeEventListener("beforeunload", beforeUnload); });
</script>
<template><PageContainer><PermissionDenied v-if="error?.permissionDenied" /><ErrorState v-else-if="error && !metadata" title="Unable to load form" :message="error.message" /><form v-else-if="metadata" class="ru-page" @submit.prevent="save(false)"><header class="ru-page__header"><div><span class="ru-eyebrow">METADATA-DRIVEN FORM · PROVISIONAL</span><h1>{{ editing ? `Edit ${metadata.label}` : `New ${metadata.label}` }}</h1><p>ERPNext remains responsible for validation and naming.</p></div><div class="ru-actions"><button type="button" @click="router.back()">Cancel</button><button class="ref-button ref-button--secondary" type="button" :disabled="saving" @click="save(true)">Save & continue</button><button class="ref-button ref-button--primary" type="submit" :disabled="saving">{{ saving ? 'Saving…' : 'Save' }}</button></div></header><div v-if="error" class="ru-validation" role="alert"><strong>Unable to save record</strong><span>{{ error.message }}</span></div><div v-if="Object.keys(errors).length" class="ru-validation" role="alert"><strong>Check the highlighted fields</strong><span v-for="message in errors" :key="message">{{ message }}</span></div><template v-for="section in sections" :key="section.key"><section v-if="section.fields.length" class="ru-card"><h2>{{ section.title }}</h2><div class="ru-form-grid"><UniversalField v-for="field in section.fields" :key="field.fieldname" :model-value="values[field.fieldname]" :field="field" :feature="feature" :error="errors[field.fieldname]" @update:model-value="change(field.fieldname, $event)" /></div></section><UniversalChildTable v-for="table in section.tables" :key="table.fieldname" :model-value="values[table.fieldname] || []" :field="table" :feature="feature" @update:model-value="change(table.fieldname, $event)" /></template><footer class="ru-sticky"><span v-if="dirty">Unsaved changes</span><button class="ref-button ref-button--primary" type="submit" :disabled="saving">Save</button></footer></form><div v-else class="ru-skeleton"><i v-for="n in 10" :key="n"></i></div></PageContainer></template>
